from fractions import Fraction

def solve(m, n, max_elements=10, max_depth=5):
    initial_set = {Fraction(m, n), Fraction(n, m)}
    queue = [(initial_set, 0)]
    visited = [initial_set]

    for current_set, depth in queue:
        if Fraction(1, 1) in current_set:
            return True
        if depth >= max_depth:
            continue

        elements = list(current_set)
        for i in range(len(elements)):
            for j in range(i + 1, len(elements)):
                x = elements[i]
                y = elements[j]

                # Arithmetic mean
                am = (x + y) / 2
                if am not in current_set:
                    new_set = current_set | {am}
                    if len(new_set) <= max_elements:
                        if new_set not in visited:
                            visited.append(new_set)
                            queue.append((new_set, depth + 1))

                # Harmonic mean
                hm = (2 * x * y) / (x + y)
                if hm not in current_set:
                    new_set = current_set | {hm}
                    if len(new_set) <= max_elements:
                        if new_set not in visited:
                            visited.append(new_set)
                            queue.append((new_set, depth + 1))
    return False

for m in range(1, 10):
    for n in range(m, 10):
        if any(m % d == 0 and n % d == 0 for d in range(2, 10)):
            continue
        if solve(m, n):
            print(f"m={m}, n={n}, m+n={m+n}")

