from fractions import Fraction

def solve_tree(m, n, max_depth=10):
    initial_set = {Fraction(m, n), Fraction(n, m)}
    if Fraction(1, 1) in initial_set:
        return True

    # Using a simple BFS where we only add one new element at a time
    queue = [(initial_set, 0)]
    visited = {frozenset(initial_set)}

    while queue:
        current_set, depth = queue.pop(0)
        if depth >= max_depth:
            continue

        elements = list(current_set)
        for i in range(len(elements)):
            for j in range(i + 1, len(elements)):
                x = elements[i]
                y = elements[j]

                for res in [(x + y) / 2, (2 * x * y) / (x + y)]:
                    if res == 1:
                        return True
                    if res not in current_set:
                        new_set = current_set | {res}
                        fs = frozenset(new_set)
                        if fs not in visited and len(new_set) <= 10:
                            visited.add(fs)
                            queue.append((new_set, depth + 1))
    return False

print(f"m=1, n=2: {solve_tree(1, 2)}")
print(f"m=1, n=3: {solve_tree(1, 3)}")
print(f"m=2, n=3: {solve_tree(2, 3)}")
print(f"m=1, n=4: {solve_tree(1, 4)}")
